import sys
from collections import defaultdict, deque

input = sys.stdin.readline

def can_achieve_condition(n, k, values, edges):
    total_xor = 0
    for value in values:
        total_xor ^= value

    if total_xor == 0:
        return "YES"

    if k == 2:
        return "NO"

    return "YES" if k - 1 >= n - 1 else "NO"

def main():
    t = int(input())
    results = []

    for _ in range(t):
        n, k = map(int, input().split())
        values = list(map(int, input().split()))
        edges = defaultdict(list)

        for _ in range(n - 1):
            u, v = map(int, input().split())
            edges[u].append(v)
            edges[v].append(u)

        results.append(can_achieve_condition(n, k, values, edges))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
